 const stone=new T.MeshStandardMaterial({map:stoneMap||null,color:0x647f8b,roughness:.88}),dark=new T.MeshStandardMaterial({color:0x1c3037}),wood=new T.MeshStandardMaterial({color:0x443b37}),aqua=new T.MeshBasicMaterial({color:0x6df7de});
