  const bell=mesh(new T.CylinderGeometry(.65,1,1.3,12,1,true),new T.MeshStandardMaterial({color:0x629c97,metalness:.7,roughness:.4}),1000,4.5,-158);box(1000,5.4,-158,5,.3,1,wood);for(const x of [997.7,1002.3])box(x,2.6,-158,.35,5.2,.35,wood);
