  const fire=new T.Sprite(fireMap?new T.SpriteMaterial({map:fireMap,transparent:true,blending:T.AdditiveBlending,depthWrite:false}):new T.SpriteMaterial({color:0xffa45c}));fire.position.set(1000,1.05,-79);fire.scale.set(2.2,2.2,1);root.add(fire);for(let i=0;i<7;i++){const a=i/7*Math.PI*2;mesh(new T.DodecahedronGeometry(.24),stone,1000+Math.sin(a)*.7,.13,-79+Math.cos(a)*.7)}lantern=new T.PointLight(0xffaa62,40,16,2);lantern.position.set(1000,1.5,-79);root.add(lantern);
