  for(const [i,[x,z,kind]] of points.entries()){const n=skeletonModel(root,kind,x,z);Object.assign(n,{id:'chapel-'+i,species:'skeleton-'+kind,kind,name:kind==='mage'?'Утопленный заклинатель':kind==='bow'?'Стрелок затопленной часовни':'Страж затопленной часовни',hp:95,maxHp:95,damage:26,home:new T.Vector3(x,0,z),target:new T.Vector3(x,0,z),heading:0,cooldown:1,attackWindup:0,aggro:null,timer:0,generation:0,hit:false});n.spawn=n.home.clone();n.island=CHAPEL_ISLANDS.find(i=>Math.hypot(x-i.x,z-i.z)<i.r)||null;mobs.push(n)}
