 function can(x,z,r=.3){return [0,Math.PI/2,Math.PI,Math.PI*1.5,...[.25,.75,1.25,1.75].map(v=>v*Math.PI)].every(a=>chapelDry(x+Math.sin(a)*r,z+Math.cos(a)*r))&&chapelDry(x,z)&&x>CHAPEL.minX+r&&x<CHAPEL.maxX-r&&z>CHAPEL.minZ+r&&z<CHAPEL.maxZ-r&&!blockers.some(b=>b.r?Math.hypot(x-b.x,z-b.z)<b.r+r:Math.abs(x-b.x)<b.w/2+r&&Math.abs(z-b.z)<b.d/2+r)}
 function npcCan(n,x,z,r=.38){return can(x,z,r)&&(!n.island||Math.hypot(x-n.island.x,z-n.island.z)<=n.island.r-r)}
 function dryPoint(x,z,r=.3){if(can(x,z,r))return new T.Vector3(x,0,z);for(let d=.5;d<130;d+=.5)for(let k=0;k<32;k++){const a=k*Math.PI/16,nx=x+Math.sin(a)*d,nz=z+Math.cos(a)*d;if(can(nx,nz,r))return new T.Vector3(nx,0,nz)}return new T.Vector3(...CHAPEL.entry).setY(0)}
 function ensureDry(){if(inside&&!can(camera.position.x,camera.position.z,.25)){const q=dryPoint(camera.position.x,camera.position.z,.25);camera.position.x=q.x;camera.position.z=q.z}}
