 function leave(){ghost.clear();inside=false;root.visible=false;clearShots();for(const n of mobs){n.aggro=null;n.attackWindup=0}setPose(origin||{position:CHAPEL.gate,yaw:0,pitch:0});document.querySelector('#location').textContent='Кладбище Темнолесья'}
 function near(point,r=2.8){return Math.hypot(camera.position.x-point[0],camera.position.z-point[2])<r}
 function action(){if(!inside)return null;if(near(CHAPEL.entry))return {type:'exit'};const i=CHAPEL.echoes.findIndex((p,i)=>!found[i]&&near(p));if(i>=0)return {type:'echo',index:i};if(near(CHAPEL.bell,3.2))return {type:'bell'};return null}
 function prompt(){const a=action();return a?.type==='exit'?'E — Вернуться на кладбище':a?.type==='echo'?'E — Разрушить оберег':a?.type==='bell'?'E — Осмотреть колокол':''}
 function collect(i){if(!Number.isInteger(i)||i<0||i>2||found[i])return false;found[i]=true;echoes[i].visible=false;return true}
 function setChoice(value){if(choice||!found.every(Boolean)||!['memory','seal'].includes(value))return false;choice=value;ghost.spawn();if(seal)seal.material.color.setHex(value==='memory'?0xd17bff:0x6df7de);if(water)water.material.color.setHex(value==='memory'?0x694483:0x246c70);return true}
 function drop(id,pos,count=1){pos=dryPoint(pos.x,pos.z,.2);const m=lootModel(root,id,count);m.position.set(pos.x,.45,pos.z);drops.push({m,id,count})}
 function killed(n){if(n===ghost.n){if(ghost.killed())drop('ectoplasm',n.g.position);return}if(!mobs.includes(n)||n.droppedGeneration===n.generation)return;n.droppedGeneration=n.generation;drop('gold',n.g.position,1+Math.floor(rand()*3));if(rand()<.3)drop('bone',n.g.position.clone().add(new T.Vector3(.45,0,0)))}
 function shoot(n){const pos=n.g.position.clone().setY(1.55),dir=camera.position.clone().sub(pos),arrow=n.kind==='bow',speed=arrow?30:23;if(arrow){const d=Math.max(.1,Math.hypot(dir.x,dir.z)),v=speed**2,disc=v*v-9.8*(9.8*d*d+2*dir.y*v);const angle=Math.atan((v-Math.sqrt(Math.max(0,disc)))/(9.8*d));dir.set(dir.x/d*Math.cos(angle),Math.sin(angle),dir.z/d*Math.cos(angle))}else dir.normalize();const m=mesh(arrow?new T.CylinderGeometry(.015,.015,.65,5):new T.OctahedronGeometry(.15),new T.MeshBasicMaterial({color:arrow?0xd0c3a1:0x64d6dc}),pos.x,pos.y,pos.z);shots.push({m,v:dir.multiplyScalar(speed),arrow,age:0,damage:n.damage})}
